import 'package:flutter/material.dart';
import '../db.dart';import '../models.dart';import '../services/backup_service.dart';import '../services/export_service.dart';
class SettingsScreen extends StatefulWidget{const SettingsScreen({super.key});@override State<SettingsScreen>createState()=>_SettingsScreenState();}
class _SettingsScreenState extends State<SettingsScreen>{
  bool _loading=true,_busy=false;final _fk=GlobalKey<FormState>();final _sn=TextEditingController();final _ph=TextEditingController();final _ad=TextEditingController();final _cu=TextEditingController();AppSettings _settings=AppSettings.defaults();
  @override void initState(){super.initState();_load();}
  @override void dispose(){_sn.dispose();_ph.dispose();_ad.dispose();_cu.dispose();super.dispose();}
  Future<void>_load()async{setState(()=>_loading=true);final s=await LocalDB.getAppSettings();if(!mounted)return;setState(()=>{_settings=s;_sn.text=s.shopName;_ph.text=s.phone;_ad.text=s.address;_cu.text=s.currency;_loading=false;});}
  void _msg(String t){if(!mounted)return;ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(t)));}
