  Future<void>_backup()async{setState(()=>_busy=true);try{await BackupService.shareBackup();_msg('تم إنشاء النسخة');}catch(e){_msg('فشل: $e');}finally{if(mounted)setState(()=>_busy=false);}}
  Future<void>_restore()async{final ok=await showDialog<bool>(context:context,builder:(ctx)=>AlertDialog(title:const Text('استرجاع'),content:const Text('سيتم استبدال جميع البيانات. متابعة؟'),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(ctx,true),child:const Text('متابعة'))]));if(ok!=true)return;setState(()=>_busy=true);try{final r=await BackupService.pickAndRestore();if(r){await _load();_msg('تم الاسترجاع');}else{_msg('تم الإلغاء');}}catch(e){_msg('فشل: $e');}finally{if(mounted)setState(()=>_busy=false);}}
  Future<void>_exp(Future<void>Function()f,String name)async{setState(()=>_busy=true);try{await f();_msg('تم تصدير $name');}catch(e){_msg('فشل: $e');}finally{if(mounted)setState(()=>_busy=false);}}
  @override Widget build(BuildContext context){if(_loading)return const Scaffold(body:Center(child:CircularProgressIndicator()));return Scaffold(appBar:AppBar(title:const Text('الإعدادات')),body:ListView(padding:const EdgeInsets.all(16),children:[Form(key:_fk,child:Column(children:[TextFormField(controller:_sn,decoration:const InputDecoration(labelText:'اسم المحل'),validator:(v)=>(v==null||v.trim().isEmpty)?'مطلوب':null),const SizedBox(height:12),TextFormField(controller:_ph,keyboardType:TextInputType.phone,decoration:const InputDecoration(labelText:'الهاتف')),const SizedBox(height:12),TextFormField(controller:_ad,maxLines:2,decoration:const InputDecoration(labelText:'العنوان')),const SizedBox(height:12),TextFormField(controller:_cu,decoration:const InputDecoration(labelText:'رمز العملة')),const SizedBox(height:16),FilledButton(onPressed:_busy?null:_save,child:const Padding(padding:EdgeInsets.symmetric(vertical:14),child:Text('حفظ')))])),const SizedBox(height:24),const Text('التصدير',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold)),const SizedBox(height:8),OutlinedButton.icon(onPressed:_busy?null:()=>_exp(ExportService.exportProductsCsv,'المخزون'),icon:const Icon(Icons.table_view),label:const Text('تصدير المخزون CSV')),const SizedBox(height:8),OutlinedButton.icon(onPressed:_busy?null:()=>_exp(ExportService.exportSalesCsv,'المبيعات'),icon:const Icon(Icons.receipt_long),label:const Text('تصدير المبيعات CSV')),const SizedBox(height:8),OutlinedButton.icon(onPressed:_busy?null:()=>_exp(ExportService.exportDebtsCsv,'الديون'),icon:const Icon(Icons.book),label:const Text('تصدير الديون CSV')),const SizedBox(height:24),const Text('النسخ الاحتياطي',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold)),const SizedBox(height:8),OutlinedButton.icon(onPressed:_busy?null:_backup,icon:const Icon(Icons.backup),label:const Text('إنشاء ومشاركة نسخة')),const SizedBox(height:12),OutlinedButton.icon(onPressed:_busy?null:_restore,icon:const Icon(Icons.restore,color:Colors.red),label:const Text('استرجاع من JSON',style:TextStyle(color:Colors.red))),const SizedBox(height:24),Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('سوقنا — الإصدار 2.0',style:TextStyle(fontWeight:FontWeight.bold)),const SizedBox(height:8),const Text('نظام إدارة محلات صغيرة، محلي أولاً.'),const SizedBox(height:8),const Text('باركود · ديون · مصروفات · جرد · كاشيرين · تقارير · تدقيق · CSV · نسخ احتياطي.')])))]));}
}
